reference_solution:
def unbounded_coin_combinations(coins, amount):
    ways = [0] * (amount + 1); ways[0] = 1
    for coin in sorted(set(coins)):
        for value in range(coin, amount + 1): ways[value] += ways[value-coin]
    return ways[amount]

